          title: "表出化と内面化の対比",
          html: '<svg viewBox="0 0 400 270" role="img" aria-label="表出化と内面化の対比図"><defs><marker id="tbAh66f2" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" class="fgah"/></marker></defs><rect x="10" y="10" width="380" height="120" rx="10" class="fgb3"/><text x="200" y="32" text-anchor="middle" font-size="12.5" font-weight="700" class="fgta">表出化（Externalization）</text><rect x="60" y="46" width="90" height="34" rx="6" class="fgb2"/><text x="105" y="68" text-anchor="middle" font-size="13" font-weight="700" class="fgta">暗黙知</text><rect x="230" y="46" width="90" height="34" rx="6" class="fgbA"/><text x="275" y="68" text-anchor="middle" font-size="13" font-weight="700" class="fgtw">形式知</text><line x1="150" y1="63" x2="228" y2="63" stroke-width="2.5" class="fgl" marker-end="url(#tbAh66f2)"/><text x="189" y="55" text-anchor="middle" font-size="9.5" font-weight="700" class="fgta">言語化</text><text x="200" y="100" text-anchor="middle" font-size="9.5" class="fgtm">例：顧客対応のノウハウを業種別マニュアル化</text><rect x="10" y="140" width="380" height="120" rx="10" class="fgb3"/><text x="200" y="162" text-anchor="middle" font-size="12.5" font-weight="700" class="fgta">内面化（Internalization）</text><rect x="60" y="176" width="90" height="34" rx="6" class="fgbA"/><text x="105" y="198" text-anchor="middle" font-size="13" font-weight="700" class="fgtw">形式知</text><rect x="230" y="176" width="90" height="34" rx="6" class="fgb2"/><text x="275" y="198" text-anchor="middle" font-size="13" font-weight="700" class="fgta">暗黙知</text><line x1="150" y1="193" x2="228" y2="193" stroke-width="2.5" class="fgl" marker-end="url(#tbAh66f2)"/><text x="189" y="185" text-anchor="middle" font-size="9.5" font-weight="700" class="fgta">体得</text><text x="200" y="230" text-anchor="middle" font-size="9.5" class="fgtm">実践を繰り返し新たな暗黙知として体得</text></svg>'
